function rotateState(rec, now) {
  if (!rec) return 'INVALID';
  if (rec.revokedAt) return 'REVOKED';
  if (now >= rec.expiresAt) return 'EXPIRED';
  if (rec.usedAt) return 'USED';
  return 'LIVE';
}

